export interface GameState {
    board: number[][];
    score: number;
    moves: number;
    bestScore: number;
    isGameOver: boolean;
    isWin: boolean;
    gameSpeed: number;
    lastMove: number;
    directions: string[];
    nextNumber: number;
    cells: { row: number; col: number; value: number }[];
}

export function initializeGameState(): GameState {
    return {
        board: Array(4).fill(null).map(() => Array(4).fill(0)),
        score: 0,
        moves: 0,
        bestScore: 0,
        isGameOver: false,
        isWin: false,
        gameSpeed: 250,
        lastMove: 0,
        directions: ['up', 'down', 'left', 'right'],
        nextNumber: 2
    };
}

export function placeRandomNumber(state: GameState): void {
    const emptyCells = [];
    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 4; j++) {
            if (state.board[i][j] === 0) {
                emptyCells.push({ row: i, col: j });
            }
        }
    }
    if (emptyCells.length > 0) {
        const index = Math.floor(Math.random() * emptyCells.length);
        const cell = emptyCells[index];
        state.board[cell.row][cell.col] = state.nextNumber === 4 ? 2 : 1;
        state.cells.push({ row: cell.row, col: cell.col, value: state.nextNumber === 4 ? 2 : 1 });
        state.nextNumber = 2;
    }
}

export function isGameOver(state: GameState): boolean {
    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 4; j++) {
            if (state.board[i][j] === 0) return false;
            if (i < 3 && state.board[i][j] === state.board[i + 1][j]) return false;
            if (j < 3 && state.board[i][j] === state.board[i][j + 1]) return false;
        }
    }
    return true;
}

export function mergeCells(state: GameState): void {
    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 3; j++) {
            if (state.board[i][j] === state.board[i][j + 1] && state.board[i][j] !== 0) {
                state.board[i][j] *= 2;
                state.board[i][j + 1] = 0;
                state.score += state.board[i][j];
                state.moves++;
            }
        }
    }
}

export function moveCells(state: GameState, direction: 'left' | 'right' | 'up' | 'down'): void {
    if (direction === 'left') {
        for (let i = 0; i < 4; i++) {
            const cells = [];
            for (let j = 0; j < 4; j++) {
                if (state.board[i][j] !== 0) cells.push(state.board[i][j]);
            }
            for (let k = 0; k < 4; k++) {
                state.board[i][k] = k < cells.length ? cells[k] : 0;
            }
            mergeCells(state);
            mergeCells(state);
        }
    } else if (direction === 'right') {
        for (let i = 0; i < 4; i++) {
            const cells = [];
            for (let j = 3; j >= 0; j--) {
                if (state.board[i][j] !== 0) cells.push(state.board[i][j]);
            }
            for (let k = 0; k < 4; k++) {
                state.board[i][3 - k] = k < cells.length ? cells[k] : 0;
            }
            mergeCells(state);
            mergeCells(state);
        }
    } else if (direction === 'up') {
        for (let j = 0; j < 4; j++) {
            const cells = [];
            for (let i = 0; i < 4; i++) {
                if (state.board[i][j] !== 0) cells.push(state.board[i][j]);
            }
            for (let k = 0; k < 4; k++) {
                state.board[k][j] = k < cells.length ? cells[k] : 0;
            }
            mergeCells(state);
            mergeCells(state);
        }
    } else if (direction === 'down') {
        for (let j = 0; j < 4; j++) {
            const cells = [];
            for (let i = 3; i >= 0; i--) {
                if (state.board[i][j] !== 0) cells.push(state.board[i][j]);
            }
            for (let k = 0; k < 4; k++) {
                state.board[3 - k][j] = k < cells.length ? cells[k] : 0;
            }
            mergeCells(state);
            mergeCells(state);
        }
    }
}

export function updateGameState(state: GameState, direction: 'left' | 'right' | 'up' | 'down'): void {
    if (isGameOver(state)) return;
    moveCells(state, direction);
    placeRandomNumber(state);
    state.moves++;
    if (state.score > state.bestScore) state.bestScore = state.score;
    if (state.moves % 3 === 0) state.gameSpeed = Math.max(50, state.gameSpeed - 10);
}

export function getGameState(state: GameState): GameState {
    return {
        board: state.board,
        score: state.score,
        moves: state.moves,
        bestScore: state.bestScore,
        isGameOver: state.isGameOver,
        isWin: state.isWin,
        gameSpeed: state.gameSpeed,
        lastMove: state.lastMove,
        directions: state.directions,
        nextNumber: state.nextNumber,
        cells: state.cells
    };
}

