export class AIOpponent {
    private gameEngine: GameEngine;
    private boardSize: number;
    private directions: number[][] = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    private bestMove: number[] = [0, 0];
    private bestScore: number = 0;
    private maxDepth: number = 3;

    constructor(gameEngine: GameEngine) {
        this.gameEngine = gameEngine;
        this.boardSize = gameEngine.getBoardSize();
    }

    public getBestMove(): number[] {
        this.bestScore = 0;
        this.bestMove = [0, 0];
        this.minimax(0, this.maxDepth, -Infinity, Infinity, true);
        return this.bestMove;
    }

    private minimax(depth: number, maxDepth: number, alpha: number, beta: number, isMaximizing: boolean): number {
        if (depth === maxDepth || this.gameEngine.isGameOver()) {
            return this.evaluateBoard();
        }

        if (isMaximizing) {
            let bestScore = -Infinity;
            for (let i = 0; i < this.boardSize; i++) {
                for (let j = 0; j < this.boardSize; j++) {
                    if (this.gameEngine.getCell(i, j) === 0) {
                        this.gameEngine.setCellValue(i, j, this.gameEngine.getHighestTile());
                        const score = this.minimax(depth + 1, maxDepth, alpha, beta, false);
                        this.gameEngine.setCellValue(i, j, 0);
                        bestScore = Math.max(bestScore, score);
                        alpha = Math.max(alpha, score);
                        if (beta <= alpha) break;
                    }
                }
            }
            return bestScore;
        } else {
            let bestScore = Infinity;
            for (let i = 0; i < this.boardSize; i++) {
                for (let j = 0; j < this.boardSize; j++) {
                    if (this.gameEngine.getCell(i, j) === 0) {
                        this.gameEngine.setCellValue(i, j, this.gameEngine.getHighestTile());
                        const score = this.minimax(depth + 1, maxDepth, alpha, beta, true);
                        this.gameEngine.setCellValue(i, j, 0);
                        bestScore = Math.min(bestScore, score);
                        beta = Math.min(beta, score);
                        if (beta <= alpha) break;
                    }
                }
            }
            return bestScore;
        }
    }

    private evaluateBoard(): number {
        const maxTile = this.gameEngine.getHighestTile();
        const blankCells = this.boardSize * this.boardSize - this.gameEngine.getFilledCells();
        const monotonicity = this.calculateMonotonicity();
        const smoothness = this.calculateSmoothness();
        return (maxTile * 100) / (this.boardSize * this.boardSize) + (blankCells * 10) / (this.boardSize * this.boardSize) + monotonicity + smoothness;
    }

    private calculateMonotonicity(): number {
        let total = 0;
        for (let i = 0; i < this.boardSize; i++) {
            let upScore = 0, downScore = 0;
            for (let j = 0; j < this.boardSize; j++) {
                const val = this.gameEngine.getCell(i, j);
                if (val > 0) {
                    upScore += val;
                    downScore += val;
                }
            }
            total += Math.abs(upScore - downScore);
        }
        return total;
    }

    private calculateSmoothness(): number {
        let total = 0;
        for (let i = 0; i < this.boardSize; i++) {
            for (let j = 0; j < this.boardSize; j++) {
                const val = this.gameEngine.getCell(i, j);
                if (val > 0) {
                    for (const [di, dj] of this.directions) {
                        const ni = i + di, nj = j + dj;
                        if (ni >= 0 && ni < this.boardSize && nj >= 0 && nj < this.boardSize && this.gameEngine.getCell(ni, nj) === val) {
                            total += val;
                        }
                    }
                }
            }
        }
        return total;
    }
}

