export function renderBoard(board: number[][], score: number, bestScore: number, moves: number, isRunning: boolean, target: HTMLElement): void {
    target.innerHTML = '';
    const container = document.createElement('div');
    container.style.display = 'grid';
    container.style.gridTemplateColumns = 'repeat(4, 1fr)';
    container.style.gap = '8px';
    container.style.padding = '16px';
    container.style.borderRadius = '12px';
    container.style.background = 'rgba(0, 0, 0, 0.3)';

    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 4; j++) {
            const cell = document.createElement('div');
            cell.style.width = '60px';
            cell.style.height = '60px';
            cell.style.borderRadius = '4px';
            cell.style.fontSize = '18px';
            cell.style.textAlign = 'center';
            cell.style.lineHeight = '60px';
            cell.style.fontWeight = 'bold';
            cell.style.color = '#ffffff';
            if (board[i][j] === 0) {
                cell.style.backgroundColor = 'rgba(255, 255, 255, 0.05)';
                cell.textContent = '';
            } else {
                const color = board[i][j] === 2 ? '#ffffff' : '#ffffff';
                cell.style.backgroundColor = board[i][j] === 2 ? '#ffffff' : '#ffffff';
                cell.textContent = board[i][j];
            }
            container.appendChild(cell);
        }
    }

    const scoreDisplay = document.createElement('div');
    scoreDisplay.textContent = `Score: ${score}`;
    scoreDisplay.style.color = '#00d9ff';
    scoreDisplay.style.fontSize = '14px';
    scoreDisplay.style.marginTop = '8px';
    container.appendChild(scoreDisplay);

    const bestScoreDisplay = document.createElement('div');
    bestScoreDisplay.textContent = `Best: ${bestScore}`;
    bestScoreDisplay.style.color = '#00d9ff';
    bestScoreDisplay.style.fontSize = '14px';
    container.appendChild(bestScoreDisplay);

    target.appendChild(container);
}
